{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "특별관리시설물 소유자가 서울시장의 부설주차장 유료화 명령 위반 시 조례상 과태료 최대 금액",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 주차장 설치 및 관리 조례 제30조 제1항에 따르면, 제22조에 따른 명령을 위반한 시설물 소유자 또는 시설물관리사업자에게는 「도시교통정비촉진법」 제60조제1항제6호에 따라 1천만원 이하의 과태료를 부과한다. 따라서 서울시장의 부설주차장 유료화 명령을 위반한 경우 조례상 과태료는 최대 1천만원이다.",
          "b_ids": "주차장:제30조제1항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
